import React from 'react';
import {
  Box,
  Button,
  Chip,
  Grid,
  LinearProgress,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import { alpha, useTheme, type Theme } from '@mui/material/styles';
import { ArrowForward as ArrowForwardIcon } from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import type { ReadinessGridItem } from './ComplianceReadinessGrid';

type ComplianceReadinessMapProps = {
  indiaItems: ReadinessGridItem[];
  exportItems: ReadinessGridItem[];
  exportVisible: boolean;
  indiaScore?: number | null;
  exportScore?: number | null;
  overallScore?: number | null;
  locale?: string;
  /** Overview-only. Enterprise keeps the quieter text links. */
  emphasizeOpenLinks?: boolean;
};

const scoreColor = (score: number | null | undefined, theme: Theme) => {
  const n = Number(score);
  if (!Number.isFinite(n)) return theme.palette.primary.main;
  if (n >= 75) return theme.palette.success.main;
  if (n >= 45) return theme.palette.warning.main;
  return theme.palette.error.main;
};

const LaneRing: React.FC<{ label: string; score?: number | null; caption: string }> = ({
  label,
  score,
  caption,
}) => {
  const theme = useTheme();
  const value = Math.max(0, Math.min(100, Number(score) || 0));
  const color = scoreColor(score, theme);
  const scoreLabel = Number.isFinite(Number(score)) ? `${Math.round(Number(score))}%` : '—';

  return (
    <Stack direction="row" spacing={1.5} alignItems="center">
      <Box sx={{ position: 'relative', width: 64, height: 64, flexShrink: 0 }}>
        <Box
          aria-hidden
          sx={{
            position: 'absolute',
            inset: 0,
            borderRadius: '50%',
            background: `conic-gradient(${color} ${value * 3.6}deg, ${alpha(theme.palette.divider, 0.35)} 0deg)`,
          }}
        />
        <Box
          sx={{
            position: 'absolute',
            inset: 4,
            borderRadius: '50%',
            bgcolor: 'background.paper',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>
            {scoreLabel}
          </Typography>
        </Box>
      </Box>
      <Box>
        <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>{label}</Typography>
        <Typography variant="caption" color="text.secondary">{caption}</Typography>
      </Box>
    </Stack>
  );
};

const neededItems = (items: ReadinessGridItem[]) =>
  items.filter((item) => {
    const status = String(item.status || '').toLowerCase();
    const score = Number(item.score);
    if (status.includes('ready') || status.includes('complete')) return false;
    if (Number.isFinite(score) && score >= (item.threshold || 75)) return false;
    return true;
  }).slice(0, 4);

const ComplianceReadinessMap: React.FC<ComplianceReadinessMapProps> = ({
  indiaItems,
  exportItems,
  exportVisible,
  indiaScore,
  exportScore,
  overallScore,
  emphasizeOpenLinks = false,
}) => {
  const theme = useTheme();
  const indiaNeeded = neededItems(indiaItems);
  const exportNeeded = neededItems(exportItems);
  const overall = Number.isFinite(Number(overallScore))
    ? Number(overallScore)
    : Math.round(((Number(indiaScore) || 0) + (exportVisible ? (Number(exportScore) || 0) : 0)) / (exportVisible ? 2 : 1));

  return (
    <Paper
      variant="outlined"
      sx={{
        p: { xs: 2, md: 2.5 },
        mb: 3,
        background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.04)} 0%, ${theme.palette.background.paper} 55%)`,
      }}
    >
      <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={2} sx={{ mb: 2 }}>
        <Box>
          <Typography variant="h6" sx={{ fontWeight: 800 }}>
            Your compliance map
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 520 }}>
            One picture of India market readiness
            {exportVisible ? ' and buyer / export packs' : ' — export tools stay hidden until you sell outside India'}.
          </Typography>
        </Box>
        <LaneRing
          label="Overall readiness"
          score={overall}
          caption="Weighted from active tracks"
        />
      </Stack>

      <Grid container spacing={2}>
        <Grid item xs={12} md={exportVisible ? 6 : 12}>
          <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
            <LaneRing
              label="India market"
              score={indiaScore}
              caption="BRSR, ISO, ZED, PAT — domestic reporting"
            />
            <Typography variant="caption" sx={{ fontWeight: 700, display: 'block', mt: 2, mb: 1 }}>
              Needed for India filings
            </Typography>
            <Stack spacing={1}>
              {indiaNeeded.length === 0 ? (
                <Chip size="small" color="success" label="India track looks healthy" />
              ) : indiaNeeded.map((item) => (
                <Box key={item.key}>
                  <Stack direction="row" justifyContent="space-between" sx={{ mb: 0.35 }}>
                    <Typography variant="body2">{item.label}</Typography>
                    <Typography variant="caption" color="text.secondary">
                      {Number.isFinite(Number(item.score)) ? `${Math.round(Number(item.score))}%` : String(item.status || 'gap')}
                    </Typography>
                  </Stack>
                  <LinearProgress
                    variant="determinate"
                    value={Math.max(8, Math.min(100, Number(item.score) || 8))}
                    sx={{ height: 6, borderRadius: 3 }}
                  />
                  {item.href ? (
                    <Button
                      component={RouterLink}
                      to={item.href}
                      size="small"
                      variant={emphasizeOpenLinks ? 'outlined' : 'text'}
                      endIcon={emphasizeOpenLinks ? <ArrowForwardIcon /> : undefined}
                      aria-label={emphasizeOpenLinks ? `Open: ${item.label}` : undefined}
                      sx={emphasizeOpenLinks
                        ? { mt: 0.75, alignSelf: 'flex-start', '&:hover': { borderColor: 'primary.main', bgcolor: 'background.paper' } }
                        : { mt: 0.5, px: 0 }}
                    >
                      Open
                    </Button>
                  ) : null}
                </Box>
              ))}
            </Stack>
          </Paper>
        </Grid>

        {exportVisible ? (
          <Grid item xs={12} md={6}>
            <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
              <LaneRing
                label="Buyer / export"
                score={exportScore}
                caption="CBAM, CDP, CSRD packs for overseas buyers"
              />
              <Typography variant="caption" sx={{ fontWeight: 700, display: 'block', mt: 2, mb: 1 }}>
                Needed for your buyers
              </Typography>
              <Stack spacing={1}>
                {exportNeeded.length === 0 ? (
                  <Chip size="small" color="success" label="Export packs look healthy" />
                ) : exportNeeded.map((item) => (
                  <Box key={item.key}>
                    <Stack direction="row" justifyContent="space-between" sx={{ mb: 0.35 }}>
                      <Typography variant="body2">{item.label}</Typography>
                      <Typography variant="caption" color="text.secondary">
                        {Number.isFinite(Number(item.score)) ? `${Math.round(Number(item.score))}%` : String(item.status || 'gap')}
                      </Typography>
                    </Stack>
                    <LinearProgress
                      variant="determinate"
                      value={Math.max(8, Math.min(100, Number(item.score) || 8))}
                      sx={{ height: 6, borderRadius: 3 }}
                    />
                    {item.href ? (
                      <Button
                        component={RouterLink}
                        to={item.href}
                        size="small"
                        variant={emphasizeOpenLinks ? 'outlined' : 'text'}
                        endIcon={emphasizeOpenLinks ? <ArrowForwardIcon /> : undefined}
                        aria-label={emphasizeOpenLinks ? `Open: ${item.label}` : undefined}
                        sx={emphasizeOpenLinks
                          ? { mt: 0.75, alignSelf: 'flex-start', '&:hover': { borderColor: 'primary.main', bgcolor: 'background.paper' } }
                          : { mt: 0.5, px: 0 }}
                      >
                        Open
                      </Button>
                    ) : null}
                  </Box>
                ))}
              </Stack>
            </Paper>
          </Grid>
        ) : null}
      </Grid>
    </Paper>
  );
};

export default ComplianceReadinessMap;
