import React from 'react';
import { Box, Button, Card, CardContent, Chip, Stack, Typography } from '@mui/material';
import { ArrowForward as ArrowForwardIcon, Lightbulb as LightbulbIcon } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import type { NextBestAction } from '../../utils/sustainabilityUx';

export interface DashboardNextBestActionProps {
  action: NextBestAction;
}

export const DashboardNextBestAction: React.FC<DashboardNextBestActionProps> = ({ action }) => {
  const navigate = useNavigate();

  return (
    <Card
      variant="outlined"
      sx={{
        mb: 3,
        borderColor: 'primary.main',
        borderWidth: 1,
        bgcolor: (theme) =>
          theme.palette.mode === 'dark' ? 'rgba(27, 94, 32, 0.12)' : 'rgba(27, 94, 32, 0.04)',
      }}
    >
      <CardContent>
        <Stack direction="row" spacing={1.5} alignItems="flex-start">
          <LightbulbIcon color="primary" sx={{ mt: 0.25 }} />
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography variant="overline" color="primary" sx={{ fontWeight: 700, letterSpacing: '0.08em' }}>
              Next best action
            </Typography>
            <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
              {action.title}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5, lineHeight: 1.55 }}>
              {action.description}
            </Typography>
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
              {action.impactLabel ? (
                <Chip size="small" color="success" variant="outlined" label={action.impactLabel} />
              ) : null}
              {action.effortLabel ? <Chip size="small" variant="outlined" label={action.effortLabel} /> : null}
            </Stack>
            <Button
              variant="contained"
              endIcon={<ArrowForwardIcon />}
              onClick={() => navigate(action.path)}
            >
              {action.ctaLabel}
            </Button>
          </Box>
        </Stack>
      </CardContent>
    </Card>
  );
};
