import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  FormControl,
  FormControlLabel,
  FormGroup,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Stack,
  Step,
  StepLabel,
  Stepper,
  TextField,
  Typography,
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import ApiService from '../../services/api';
import { useResponsiveStepperOrientation } from '../../hooks/useResponsiveStepperOrientation';
import { getStoredSignupGoal } from '../../constants/signupGoals';

const STEPS = ['Organization', 'Regulatory mandates', 'Contact', 'Review'];

const EnterpriseRegistration: React.FC = () => {
  const navigate = useNavigate();
  const { orientation: stepperOrientation } = useResponsiveStepperOrientation();
  const [activeStep, setActiveStep] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [form, setForm] = useState({
    companyName: '',
    cinNumber: '',
    gstNumber: '',
    panNumber: '',
    industry: '',
    sector: '',
    listingStatus: 'unlisted',
    stockExchanges: [] as string[],
    isin: '',
    scripCode: '',
    reportingEntityType: 'consolidated',
    consolidationApproach: 'operational_control',
    contact: {
      email: '',
      phone: '',
      address: { street: '', city: '', state: '', pincode: '', country: 'India' },
    },
    regulatoryMandates: {
      sebiBrsr: true,
      brsrCoreValueChain: true,
      patScheme: false,
      indianCarbonMarket: false,
      greenCreditProgramme: false,
      cbamExport: false,
    },
  });

  const update = (field: string, value: unknown) => {
    setForm((prev) => ({ ...prev, [field]: value }));
  };

  useEffect(() => {
    const goal = getStoredSignupGoal();
    if (!goal) return;
    setForm((prev) => {
      const mandates = { ...prev.regulatoryMandates };
      if (goal === 'brsr_compliance' || goal === 'buyer_audit') {
        mandates.sebiBrsr = true;
        mandates.brsrCoreValueChain = true;
      }
      if (goal === 'pat_icm') {
        mandates.patScheme = true;
        mandates.indianCarbonMarket = true;
      }
      if (goal === 'baseline_footprint' || goal === 'cost_reduction') {
        mandates.sebiBrsr = true;
      }
      return { ...prev, regulatoryMandates: mandates };
    });
  }, []);

  const handleSubmit = async () => {
    setError(null);
    setSubmitting(true);
    try {
      const response = await ApiService.registerEnterprise({
        ...form,
        cinNumber: form.cinNumber.toUpperCase(),
      });
      if (!response?.success) {
        throw new Error(response?.message || 'Registration failed');
      }
      navigate('/enterprise/workflow');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Registration failed');
    } finally {
      setSubmitting(false);
    }
  };

  const renderStep = () => {
    switch (activeStep) {
      case 0:
        return (
          <Stack spacing={2}>
            <TextField
              label="Legal entity name"
              required
              fullWidth
              value={form.companyName}
              onChange={(e) => update('companyName', e.target.value)}
            />
            <TextField
              label="CIN"
              required
              fullWidth
              value={form.cinNumber}
              onChange={(e) => update('cinNumber', e.target.value)}
              helperText="Corporate Identity Number (SEBI / MCA)"
            />
            <TextField
              label="Industry"
              required
              fullWidth
              value={form.industry}
              onChange={(e) => update('industry', e.target.value)}
            />
            <FormControl fullWidth>
              <InputLabel>Listing status</InputLabel>
              <Select
                label="Listing status"
                value={form.listingStatus}
                onChange={(e) => update('listingStatus', e.target.value)}
              >
                <MenuItem value="listed">Listed (BSE/NSE)</MenuItem>
                <MenuItem value="unlisted">Large unlisted</MenuItem>
                <MenuItem value="subsidiary_of_listed">Subsidiary of listed group</MenuItem>
                <MenuItem value="public_sector">Public sector enterprise</MenuItem>
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Reporting entity</InputLabel>
              <Select
                label="Reporting entity"
                value={form.reportingEntityType}
                onChange={(e) => update('reportingEntityType', e.target.value)}
              >
                <MenuItem value="consolidated">Consolidated</MenuItem>
                <MenuItem value="standalone">Standalone</MenuItem>
                <MenuItem value="holding_company">Holding company</MenuItem>
              </Select>
            </FormControl>
            {(form.listingStatus === 'listed' || form.listingStatus === 'subsidiary_of_listed') && (
              <>
                <FormControl fullWidth>
                  <InputLabel>Stock exchange</InputLabel>
                  <Select
                    label="Stock exchange"
                    value={form.stockExchanges[0] || ''}
                    onChange={(e) => update('stockExchanges', e.target.value ? [e.target.value] : [])}
                  >
                    <MenuItem value="BSE">BSE</MenuItem>
                    <MenuItem value="NSE">NSE</MenuItem>
                    <MenuItem value="both">BSE and NSE</MenuItem>
                  </Select>
                </FormControl>
                <TextField
                  label="ISIN"
                  fullWidth
                  value={form.isin}
                  onChange={(e) => update('isin', e.target.value.toUpperCase())}
                />
                <TextField
                  label="Scrip code"
                  fullWidth
                  value={form.scripCode}
                  onChange={(e) => update('scripCode', e.target.value)}
                />
              </>
            )}
          </Stack>
        );
      case 1:
        return (
          <FormGroup>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Select Indian government mandates applicable to your organization. The workflow adapts to your selections.
            </Typography>
            {(
              [
                ['sebiBrsr', 'SEBI BRSR (top 1000 / listed)'],
                ['brsrCoreValueChain', 'BRSR Core value chain'],
                ['patScheme', 'PAT — energy intensity (designated consumer)'],
                ['indianCarbonMarket', 'Indian Carbon Market (ICM)'],
                ['greenCreditProgramme', 'Green Credit Programme'],
                ['cbamExport', 'EU CBAM export readiness'],
              ] as const
            ).map(([key, label]) => (
              <FormControlLabel
                key={key}
                control={(
                  <Checkbox
                    checked={form.regulatoryMandates[key]}
                    onChange={(e) => update('regulatoryMandates', {
                      ...form.regulatoryMandates,
                      [key]: e.target.checked,
                    })}
                  />
                )}
                label={label}
              />
            ))}
          </FormGroup>
        );
      case 2:
        return (
          <Stack spacing={2}>
            <TextField
              label="Contact email"
              type="email"
              required
              fullWidth
              value={form.contact.email}
              onChange={(e) => update('contact', { ...form.contact, email: e.target.value })}
            />
            <TextField
              label="Phone"
              required
              fullWidth
              value={form.contact.phone}
              onChange={(e) => update('contact', { ...form.contact, phone: e.target.value })}
            />
            <TextField
              label="City"
              fullWidth
              value={form.contact.address.city}
              onChange={(e) => update('contact', {
                ...form.contact,
                address: { ...form.contact.address, city: e.target.value },
              })}
            />
            <TextField
              label="State"
              fullWidth
              value={form.contact.address.state}
              onChange={(e) => update('contact', {
                ...form.contact,
                address: { ...form.contact.address, state: e.target.value },
              })}
            />
          </Stack>
        );
      default:
        return (
          <Box>
            <Typography variant="body1" gutterBottom>
              <strong>{form.companyName}</strong> — CIN {form.cinNumber}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              After submission, complete the guided compliance workflow aligned with SEBI BRSR, PAT, and related Indian mandates.
            </Typography>
          </Box>
        );
    }
  };

  return (
    <Paper sx={{ p: { xs: 2, md: 4 }, maxWidth: 720, mx: 'auto' }}>
      <Typography variant="h5" sx={{ fontWeight: 700, mb: 1 }}>
        Enterprise / corporation registration
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        For large companies subject to SEBI BRSR, value-chain disclosure, and national carbon programmes.
      </Typography>
      <Stepper activeStep={activeStep} orientation={stepperOrientation} sx={{ mb: 3 }}>
        {STEPS.map((label) => (
          <Step key={label}>
            <StepLabel>{label}</StepLabel>
          </Step>
        ))}
      </Stepper>
      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {renderStep()}
      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ mt: 3 }}>
        <Button disabled={activeStep === 0} onClick={() => setActiveStep((s) => s - 1)}>
          Back
        </Button>
        {activeStep < STEPS.length - 1 ? (
          <Button variant="contained" onClick={() => setActiveStep((s) => s + 1)}>
            Next
          </Button>
        ) : (
          <Button variant="contained" disabled={submitting} onClick={handleSubmit}>
            {submitting ? 'Submitting…' : 'Create enterprise profile'}
          </Button>
        )}
      </Stack>
    </Paper>
  );
};

export default EnterpriseRegistration;
